column7:
{'@type': 'Syllabus', 'name': 'Week 1', 'description': 'Unit 1This week we are going to learn the general information about the Japanese language, the basics of phonetics and pronunciation, grammar structure of the Japanese sentences, and the first letters of hiragana script.', 'timeRequired': 'PT3H'}
{'@type': 'Syllabus', 'name': 'Week 2', 'description': "Unit 2This week's grammar materials contain the information about Japanese pronouns, the structure of a simple declarative sentence. In writing lessons you are going to learn how to write new hiragana letters.", 'timeRequired': 'PT4H'}
{'@type': 'Syllabus', 'name': 'Week 3', 'description': 'Unit 3This week you are going to learn how Japanese verbs and adjectives change their form, as well as learn new Japanese suffixes. Writing lessons introduce another Japanese script - katakana.', 'timeRequired': 'PT5H'}
{'@type': 'Syllabus', 'name': 'Week 4', 'description': 'Unit 4This week you are going to learn to introduce new objects and adverbial modifiers, ask new questions. In writing lessons you will learn the rules of voicing and invoicing in the katakana script.', 'timeRequired': 'PT3H'}
{'@type': 'Syllabus', 'name': 'Week 5', 'description': 'Unit 5In this unit there will be less new grammar rules, and main attention will be paid to lexical aspects, as well as to etiquette and polite forms. In the writing lessons you will learn how to write your first characters.', 'timeRequired': 'PT5H'}

[
  {
    "@type": "Syllabus",
    "name": "Welcome to the course",
    "description": "This module introduces the course agenda.",
    "timeRequired": "PT0.25H"
  },
  {
    "@type": "Syllabus",
    "name": "Building conversational experiences with Dialogflow",
    "description": "This module gives an introduction of conversational agents (chatbots), reviews the evolution of, and
challenges designing for rich natural language, conversational agents, and introduces Dialogflow as a tool for such experiences.",
    "timeRequired": "PT0.27H"
  },
  {
    "@type": "Syllabus",
    "name": "Defining Intents and Entities",
    "description": "This module covers the basic building blocks of designing a conversational agent in Dialogflow",
    "timeRequired": "PT2H"
  },
  {
    "@type": "Syllabus",
    "name": "Maintaining context and taking actions",
    "description": "This module continues to extend your agent's capabilities to be able to understand context and fulfill actions.",
    "timeRequired": "PT2H"
  },
  {
    "@type": "Syllabus",
    "name": "Taking your chatbot to production",
    "description": "This module takes a look at how you can operationalize your agent...in other words what you need to do to take your chatbot into production.",
    "timeRequired": "PT4H"
  },
  {
    "@type": "Syllabus",
    "name": "Additional Features",
    "description": "This module discusses some of the beta features that you can experiment with you to further enhance your chatbot",
    "timeRequired": "PT0.2H"
  },
  {
    "@type": "Syllabus",
    "name": "Summary",
    "description": "This module covers a summary of all the topics so far",
    "timeRequired": "PT0.03H"
  }
]
